import * as THREE from 'three/webgpu';
import { color, uniform, vec3, mix, uv, float } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'testimonial-panel';
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  const W = 3.4, H = 1.9;
  const disposables = [];
  const timelines = [];

  // --- Panel ---
  const panelGeo = new THREE.PlaneGeometry(W, H, 1, 1);
  disposables.push(panelGeo);

  const topColor = color('#1a1a22');
  const bottomColor = color('#111116');
  const vUv = uv();
  const gradientNode = mix(topColor, bottomColor, vUv.y.oneMinus());

  const panelMat = new THREE.MeshStandardNodeMaterial();
  panelMat.colorNode = gradientNode;
  panelMat.roughness = 0.6;
  panelMat.metalness = 0.2;
  panelMat.clearcoat = 0.1;
  disposables.push(panelMat);

  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, 0);
  root.add(panel);

  // hairline border
  const borderGeo = new THREE.PlaneGeometry(W + 0.006, H + 0.006, 1, 1);
  disposables.push(borderGeo);
  const borderMat = new THREE.MeshBasicNodeMaterial();
  borderMat.colorNode = color('#26262f');
  borderMat.transparent = true;
  disposables.push(borderMat);
  const border = new THREE.Mesh(borderGeo, borderMat);
  border.position.set(0, 0, -0.001);
  root.add(border);

  // helper: convert px scale to scene units approx (using fontSize / 62 as base ratio to spec'd em heights)
  // quote-mark: 62px -> 0.62 units tall => scale factor 0.01 per px
  const PX_TO_UNIT = 0.01;

  // top-left padding 0.5 units (2x base unit 0.25)
  const padX = -W / 2 + 0.5;
  const padTop = H / 2 - 0.5;

  // --- Quote mark glyph ---
  const quoteMarkMesh = createTextMesh({
    text: '\u201C',
    fontAtlas: ctx.fontAtlas,
    family: 'Lora',
    fontWeight: 600,
    fontSize: 62 * PX_TO_UNIT,
    letterSpacing: 0,
    lineHeight: 1,
    color: '#ff2a38',
    maxWidth: 1.0,
  });
  quoteMarkMesh.position.set(padX, padTop, 0.04);
  quoteMarkMesh.userData.baseScale = 1.0;
  root.add(quoteMarkMesh);
  disposables.push(quoteMarkMesh);

  if (quoteMarkMesh.material) {
    quoteMarkMesh.material.roughness = 0.5;
    quoteMarkMesh.material.metalness = 0.3;
  }

  // --- Quote text ---
  const quoteTop = padTop - 0.62 - 0.25;
  const quoteMesh = createTextMesh({
    text: config.textContent?.[1]?.text ??
      'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    fontAtlas: ctx.fontAtlas,
    family: 'Lora',
    fontWeight: 400,
    fontSize: 20 * PX_TO_UNIT,
    letterSpacing: 0,
    lineHeight: 1.45,
    color: '#e8ecf2',
    maxWidth: 2.4,
  });
  quoteMesh.position.set(padX, quoteTop, 0.03);
  root.add(quoteMesh);
  disposables.push(quoteMesh);

  // estimate quote block height for attribution offset (rough: 2 lines at 20px * 1.45 lineHeight)
  const estimatedQuoteHeight = 20 * PX_TO_UNIT * 1.45 * 3; // ~3 lines
  const attrTop = quoteTop - estimatedQuoteHeight - 0.25;

  // accent rule
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02, 1, 1);
  disposables.push(ruleGeo);
  const ruleMat = new THREE.MeshBasicNodeMaterial();
  ruleMat.colorNode = color('#ff2a38').mul(1.4);
  disposables.push(ruleMat);
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(padX + 0.1, attrTop, 0.02);
  root.add(rule);

  // attribution
  const attrMesh = createTextMesh({
    text: 'M. OKAFOR',
    fontAtlas: ctx.fontAtlas,
    family: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 13 * PX_TO_UNIT,
    letterSpacing: 0.08,
    lineHeight: 1.2,
    color: '#e8ecf2',
    maxWidth: 2.4,
  });
  attrMesh.position.set(padX + 0.25, attrTop, 0.02);
  root.add(attrMesh);
  disposables.push(attrMesh);

  // caption
  const captionMesh = createTextMesh({
    text: 'COLLECTOR SINCE 2019',
    fontAtlas: ctx.fontAtlas,
    family: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 9 * PX_TO_UNIT,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#8a8a94',
    maxWidth: 2.4,
  });
  captionMesh.position.set(padX + 0.25, attrTop - 0.15, 0.02);
  root.add(captionMesh);
  disposables.push(captionMesh);

  // --- Animation ---
  root.visible = true;
  const startY = root.position.y;
  root.position.y = startY + 0.2;
  root.traverse((o) => {
    if (o.material) o.material.transparent = true;
  });
  panelMat.opacity = 0;
  borderMat.opacity = 0;
  [quoteMesh, attrMesh, captionMesh, rule].forEach((m) => {
    if (m.material) m.material.opacity = 0;
  });
  quoteMarkMesh.scale.setScalar(1.0);
  if (quoteMarkMesh.material) quoteMarkMesh.material.opacity = 0;

  const tl = gsap.timeline();
  timelines.push(tl);

  tl.to(root.position, {
    y: startY,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);

  const fadeTargets = [panelMat, borderMat];
  fadeTargets.forEach((m) => {
    tl.to(m, { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
  });

  [quoteMesh, attrMesh, captionMesh, rule].forEach((m) => {
    if (m.material) {
      tl.to(m.material, { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
    }
  });

  if (quoteMarkMesh.material) {
    tl.to(quoteMarkMesh.material, { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }, 0);
  }

  quoteMarkMesh.scale.setScalar(1.04);
  tl.to(quoteMarkMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  }, 0.5);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
      if (d && d.geometry && typeof d.geometry.dispose === 'function') d.geometry.dispose();
      if (d && d.material && typeof d.material.dispose === 'function') d.material.dispose();
    });
  };

  return root;
}
